const sourceItems = $items("Parse Draft JSON", 0, 0).map(i => i.json);
const reelSource = sourceItems.find(r => String(r.content_type || "").toLowerCase() === "reel") || sourceItems[0];

if (!reelSource) return [];

const row = reelSource;
let scenes = [];
