  scenario: { reality_type: 'inefficiency_reason', fix_type: 'simple_rule', cta_type: 'share_to_friend', question_type: 'will_you_continue', angle_category: 'repetition', cta_tone: 'social' }
};

function hashText(text) {
  const str = String(text || '');
  let hash = 0;
  for (let i = 0; i < str.length; i += 1) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash);
}

function splitHook(text) {
  const parts = String(text || '').trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return ['', ''];
  if (parts.length === 1) return [parts[0], ''];
  const splitAt = Math.max(1, Math.ceil(parts.length / 2));
  return [parts.slice(0, splitAt).join(' '), parts.slice(splitAt).join(' ')];
}

function parseList(value) {
  if (Array.isArray(value)) {
    return value.map(v => String(typeof v === 'object' ? (v.hook || v.selected_hook || v.structure || '') : v || '').trim()).filter(Boolean);
  }
  const text = String(value || '').trim();
  if (!text) return [];
  try {
    const parsed = JSON.parse(text);
    if (Array.isArray(parsed)) {
      return parsed.map(v => String(typeof v === 'object' ? (v.hook || v.selected_hook || v.structure || '') : v || '').trim()).filter(Boolean);
    }
  } catch (e) {}
  return text.split(/[,\n]+/).map(v => String(v || '').trim()).filter(Boolean);
}

