    const tb = new Date(String(b.approved_at || b.analysis_generated_at || b.timestamp || 0)).getTime() || 0;
    if (tb !== ta) return tb - ta;
    return String(b.validation_batch_id || '').localeCompare(String(a.validation_batch_id || ''));
  })[0] || null;
}

function detectIntent(row) {
  const text = [row.title, row.final_title, row.body, row.subtitles, row.caption]
    .map(v => String(v || '').toLowerCase())
    .join(' ');
  if (/(shop|owner|store|inventory|margin|operation|risk|business)/i.test(text)) return 'shop_owner';
  if (/(you|customer)/i.test(text)) return 'user';
  return 'mixed';
}

