function selectHook(structureType, seedSource) {
  const categories = hookCategoryByStructure[structureType] || ['loss'];
  const uniquePool = [];
  for (const category of categories) {
    const hooks = hookLibrary[category] || [];
    const start = Number(cursorState[category] || 0) % (hooks.length || 1);
    for (let i = 0; i < hooks.length; i += 1) {
      const hook_text = hooks[(start + i) % hooks.length];
      const key = `${category}|${hook_text}`;
      if (!uniquePool.some(x => x.key === key)) {
        uniquePool.push({ hook_category: category, hook_text, key });
      }
    }
  }
  const allPool = uniquePool.length ? uniquePool : Object.entries(hookLibrary).flatMap(([category, hooks]) => hooks.map(hook_text => ({ hook_category: category, hook_text, key: `${category}|${hook_text}` })));
  const approvedPrimarySet = new Set(approvedPrimaryHooks);
  const approvedSecondarySet = new Set(approvedSecondaryHooks);
  const approvedSuppressedSet = new Set(approvedSuppressedHooks);
  const winnerSet = new Set(winnerRecommendedHooks);
  const suppressedSet = new Set(winnerSuppressedHooks);
  const recentFiltered = allPool.filter(item => !recentHookKeys.has(item.key));
  const basePool = recentFiltered.length ? recentFiltered : allPool;

  let pool = basePool;
  let hook_source = 'fallback_library';
  let hook_mode = approvedControlValid ? 'approved_priority' : (winnerSummaryValid ? 'winner_priority' : 'fallback');

  if (approvedControlValid) {
    const approvedPrimaryPool = basePool.filter(item => approvedPrimarySet.has(item.hook_text));
    const approvedSecondaryPool = basePool.filter(item => approvedSecondarySet.has(item.hook_text));
    const approvedSuppressedPool = basePool.filter(item => approvedSuppressedSet.has(item.hook_text));
    if (approvedPrimaryPool.length) {
      pool = approvedPrimaryPool;
      hook_source = 'approved_primary';
    } else if (approvedSecondaryPool.length) {
      pool = approvedSecondaryPool;
      hook_source = 'approved_secondary';
    } else if (approvedSuppressedPool.length) {
      pool = approvedSuppressedPool;
      hook_source = 'approved_suppressed';
    } else {
      pool = basePool.length ? basePool : allPool;
      hook_source = 'fallback_library';
    }
  } else if (winnerSummaryValid) {
    const recommendedPool = basePool.filter(item => winnerSet.has(item.hook_text));
    const neutralPool = basePool.filter(item => !winnerSet.has(item.hook_text) && !suppressedSet.has(item.hook_text));
    const fallbackSuppressedPool = basePool.filter(item => suppressedSet.has(item.hook_text));
    if (recommendedPool.length) {
      pool = recommendedPool;
      hook_source = 'winner_recommended';
    } else if (neutralPool.length) {
      pool = neutralPool;
      hook_source = 'winner_neutral';
    } else if (fallbackSuppressedPool.length) {
      pool = fallbackSuppressedPool;
      hook_source = 'winner_fallback_suppressed';
    } else {
      pool = basePool.length ? basePool : allPool;
      hook_source = 'fallback_library';
    }
  }

  if (!pool.length) {
    pool = allPool;
    hook_source = 'fallback_library';
  }

  const picked = pool[hashText(seedSource) % pool.length];
  const hooks = hookLibrary[picked.hook_category] || [];
  const pickedIndex = hooks.indexOf(picked.hook_text);
  cursorState[picked.hook_category] = hooks.length ? (pickedIndex + 1) % hooks.length : 0;
  const hook_lines = splitHook(picked.hook_text);

  return {
    ...picked,
    hook_lines,
    hook_display: hook_lines.join('\n'),
    hook_mode,
    hook_source,
    validation_batch_id_source: validationBatchIdSource,
    approved_primary_hooks: approvedControlValid ? JSON.stringify(approvedPrimaryHooks) : '[]',
    approved_secondary_hooks: approvedControlValid ? JSON.stringify(approvedSecondaryHooks) : '[]',
    approved_suppressed_hooks: approvedControlValid ? JSON.stringify(approvedSuppressedHooks) : '[]'
  };
}

