function num(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

function pct(value) {
  return Number.parseFloat(Number(value || 0).toFixed(2));
}

function toKstDate(ts) {
  const d = new Date(String(ts || ''));
  if (Number.isNaN(d.getTime())) return '';
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Seoul',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(d);
}

function summarize(map, keyField, statusField) {
  return [...map.values()].map(entry => {
    const avgScore = entry.total_posts ? entry.total_score / entry.total_posts : 0;
    return {
      [keyField]: entry[keyField],
      total_posts: entry.total_posts,
      total_score: Number(entry.total_score.toFixed(2)),
      avg_score: pct(avgScore),
      dm_hits: entry.dm_hits,
      [statusField]: 'neutral'
    };
  }).sort((a, b) => b.avg_score - a.avg_score || b.dm_hits - a.dm_hits || b.total_posts - a.total_posts || String(a[keyField]).localeCompare(String(b[keyField])));
}

function scoreRow(row) {
  return num(row.likes) + (num(row.saves) * 3) + (num(row.comments) * 4) + ((String(row.dm_triggered).toLowerCase() === 'true' || row.dm_triggered === true) ? 8 : 0);
}

const analysisGeneratedAt = new Date().toISOString();
const timestamps = latest.map(r => r.timestamp).filter(Boolean);
const batchStart = toKstDate(timestamps[timestamps.length - 1] || timestamps[0] || analysisGeneratedAt);
const batchEnd = toKstDate(timestamps[0] || analysisGeneratedAt);
const validationBatchId = batchStart && batchEnd ? `window-${batchStart}_${batchEnd}` : `window-${analysisGeneratedAt.slice(0, 10)}`;

const hookMap = new Map();
const structureMap = new Map();

for (const row of latest) {
  const hook = String(row.hook || '').trim();
  const structure = String(row.structure || '').trim();
  if (!hook || !structure) continue;
  const score = scoreRow(row);
  if (!hookMap.has(hook)) hookMap.set(hook, { hook, total_posts: 0, total_score: 0, dm_hits: 0 });
  if (!structureMap.has(structure)) structureMap.set(structure, { structure, total_posts: 0, total_score: 0, dm_hits: 0 });
  const hookEntry = hookMap.get(hook);
  const structureEntry = structureMap.get(structure);
  hookEntry.total_posts += 1;
  hookEntry.total_score += score;
  hookEntry.dm_hits += (String(row.dm_triggered).toLowerCase() === 'true' || row.dm_triggered === true) ? 1 : 0;
  structureEntry.total_posts += 1;
  structureEntry.total_score += score;
  structureEntry.dm_hits += (String(row.dm_triggered).toLowerCase() === 'true' || row.dm_triggered === true) ? 1 : 0;
}

let hookSummaries = summarize(hookMap, 'hook', 'hook_status');
let structureSummaries = summarize(structureMap, 'structure', 'structure_status');

const hookMean = hookSummaries.length ? hookSummaries.reduce((sum, item) => sum + item.avg_score, 0) / hookSummaries.length : 0;
const structureMean = structureSummaries.length ? structureSummaries.reduce((sum, item) => sum + item.avg_score, 0) / structureSummaries.length : 0;
const hookVariance = hookSummaries.length ? hookSummaries.reduce((sum, item) => sum + Math.pow(item.avg_score - hookMean, 2), 0) / hookSummaries.length : 0;
const structureVariance = structureSummaries.length ? structureSummaries.reduce((sum, item) => sum + Math.pow(item.avg_score - structureMean, 2), 0) / structureSummaries.length : 0;
const hookUpper = hookMean + Math.sqrt(hookVariance) * 0.25;
const hookLower = hookMean - Math.sqrt(hookVariance) * 0.25;
const structureUpper = structureMean + Math.sqrt(structureVariance) * 0.25;
const structureLower = structureMean - Math.sqrt(structureVariance) * 0.25;

for (const item of hookSummaries) {
  if (hookSummaries.length === 1) {
    item.hook_status = 'winner';
  } else if (item.avg_score >= hookUpper || (item.dm_hits > 0 && item.avg_score >= hookMean)) {
    item.hook_status = 'winner';
  } else if (item.avg_score <= hookLower && item.dm_hits === 0) {
    item.hook_status = 'loser';
  }
}

for (const item of structureSummaries) {
  if (structureSummaries.length === 1) {
    item.structure_status = 'winner';
  } else if (item.avg_score >= structureUpper || (item.dm_hits > 0 && item.avg_score >= structureMean)) {
    item.structure_status = 'winner';
  } else if (item.avg_score <= structureLower && item.dm_hits === 0) {
    item.structure_status = 'loser';
  }
}

if (!hookSummaries.some(item => item.hook_status === 'winner') && hookSummaries.length) hookSummaries[0].hook_status = 'winner';
if (!hookSummaries.some(item => item.hook_status === 'loser') && hookSummaries.length > 1) hookSummaries[hookSummaries.length - 1].hook_status = 'loser';
if (!structureSummaries.some(item => item.structure_status === 'winner') && structureSummaries.length) structureSummaries[0].structure_status = 'winner';
if (!structureSummaries.some(item => item.structure_status === 'loser') && structureSummaries.length > 1) structureSummaries[structureSummaries.length - 1].structure_status = 'loser';

const hookWinners = hookSummaries.filter(item => item.hook_status === 'winner');
const hookLosers = hookSummaries.filter(item => item.hook_status === 'loser');
const structureWinners = structureSummaries.filter(item => item.structure_status === 'winner');
const structureLosers = structureSummaries.filter(item => item.structure_status === 'loser');

const hookPerformanceSummary = hookSummaries.map(item => ({
  hook: item.hook,
  total_posts: item.total_posts,
  total_score: item.total_score,
  avg_score: item.avg_score,
