  total_score: item.total_score,
  avg_score: item.avg_score,
  dm_hits: item.dm_hits,
  structure_status: item.structure_status
}));

const recommendedHooks = hookWinners.map(item => item.hook);
const suppressedHooks = hookLosers.map(item => item.hook);

return [
