];

const rows = $input.all().map(i => i.json || {});
const cutoff = Date.now() - (7 * 24 * 60 * 60 * 1000);

function toMs(value) {
  const n = new Date(String(value || '')).getTime();
  return Number.isFinite(n) ? n : 0;
}

function num(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

function pct(value) {
  return Number.parseFloat(Number(value || 0).toFixed(2));
}

function stringify(value) {
  return JSON.stringify(value);
}

const windowRows = rows
  .filter(r => ['validation_post', 'winner_priority_post'].includes(String(r.record_type || '').trim()))
  .filter(r => toMs(r.timestamp || r.analysis_generated_at) >= cutoff)
  .filter(r => String(r.hook || '').trim() && String(r.structure || '').trim())
  .sort((a, b) => (toMs(b.timestamp || b.analysis_generated_at) - toMs(a.timestamp || a.analysis_generated_at)));

if (windowRows.length < 30) return [];

function scoreRow(row) {
  return num(row.likes) + (num(row.saves) * 4) + (num(row.comments) * 5) + ((String(row.dm_triggered).toLowerCase() === 'true' || row.dm_triggered === true) ? 10 : 0);
}

function aggregate(items, keyField) {
  const map = new Map();
  for (const row of items) {
    const key = String(row[keyField] || '').trim();
    if (!key) continue;
    const score = scoreRow(row);
    if (!map.has(key)) map.set(key, { [keyField]: key, total_posts: 0, total_score: 0, dm_hits: 0, scores: [] });
    const entry = map.get(key);
    entry.total_posts += 1;
    entry.total_score += score;
    entry.dm_hits += (String(row.dm_triggered).toLowerCase() === 'true' || row.dm_triggered === true) ? 1 : 0;
    entry.scores.push(score);
  }
  return [...map.values()].map(entry => {
    const mean = entry.total_posts ? entry.total_score / entry.total_posts : 0;
    const variance = entry.scores.length ? entry.scores.reduce((sum, s) => sum + Math.pow(s - mean, 2), 0) / entry.scores.length : 0;
    const consistency_score = Number((1 / (1 + variance)).toFixed(4));
    return {
      [keyField]: entry[keyField],
      total_posts: entry.total_posts,
      total_score: Number(entry.total_score.toFixed(2)),
      avg_score: pct(mean),
      dm_hits: entry.dm_hits,
      consistency_score
    };
  }).sort((a, b) => b.avg_score - a.avg_score || b.dm_hits - a.dm_hits || b.consistency_score - a.consistency_score || b.total_posts - a.total_posts || String(a[keyField]).localeCompare(String(b[keyField])));
}

const hooks = aggregate(windowRows, 'hook');
const structures = aggregate(windowRows, 'structure');
if (!hooks.length || !structures.length) return [];

const hookCount = hooks.length;
const structureCount = structures.length;
const coreCount = Math.max(1, Math.ceil(hookCount * 0.3));
const suppressedCount = Math.max(1, Math.ceil(hookCount * 0.45));
const structureCoreCount = Math.max(1, Math.ceil(structureCount * 0.33));
const structureSuppressedCount = Math.max(1, Math.ceil(structureCount * 0.34));

const hookMedian = hooks[Math.floor((hookCount - 1) / 2)]?.avg_score || 0;
const coreSet = new Set();
const suppressedSet = new Set();

for (const item of hooks.slice(0, coreCount)) {
  coreSet.add(item.hook);
}
for (const item of hooks) {
  if (item.dm_hits > 0 && item.avg_score >= hookMedian) coreSet.add(item.hook);
}

const weakCandidates = hooks
  .filter(item => item.dm_hits === 0 && item.avg_score <= hookMedian)
  .slice(-suppressedCount);
for (const item of weakCandidates) {
  if (!coreSet.has(item.hook)) suppressedSet.add(item.hook);
}
for (const item of hooks.slice(-suppressedCount)) {
  if (!coreSet.has(item.hook)) suppressedSet.add(item.hook);
}

const secondarySet = hooks.map(item => item.hook).filter(h => !coreSet.has(h) && !suppressedSet.has(h));

const compressedHookSet = hooks.filter(item => coreSet.has(item.hook)).map(item => item.hook);
const secondaryHooks = secondarySet;
const suppressedHooks = [...suppressedSet];
const conversionHooks = hooks.filter(item => item.dm_hits > 0).map(item => item.hook);

const hookRows = hooks.map(item => ({
  json: {
    record_type: '7d_hook_analysis',
    analysis_generated_at: new Date().toISOString(),
    analysis_window_start: new Date(cutoff).toISOString(),
    analysis_window_end: new Date().toISOString(),
    hook: item.hook,
    structure: '',
    total_posts: item.total_posts,
    total_score: item.total_score,
    avg_score: item.avg_score,
    dm_hits: item.dm_hits,
    consistency_score: item.consistency_score,
    hook_status: coreSet.has(item.hook) ? 'core' : (suppressedSet.has(item.hook) ? 'suppressed' : 'secondary'),
    structure_status: ''
  }
}));

const structureRanking = structures.map((item, idx) => ({
  structure: item.structure,
  total_posts: item.total_posts,
  total_score: item.total_score,
  avg_score: item.avg_score,
  dm_hits: item.dm_hits,
  consistency_score: item.consistency_score,
  structure_status: idx < structureCoreCount ? 'core' : (idx >= structureCount - structureSuppressedCount ? 'suppressed' : 'secondary')
}));

const summaryRow = {
  json: {
    record_type: '7d_compression_summary',
    analysis_generated_at: new Date().toISOString(),
    analysis_window_start: new Date(cutoff).toISOString(),
    analysis_window_end: new Date().toISOString(),
    hook_status: 'core',
    structure_status: 'core',
    compressed_hook_set: stringify(compressedHookSet),
    conversion_hooks: stringify(conversionHooks),
    next_cycle_hooks_primary: stringify(compressedHookSet),
    next_cycle_hooks_secondary: stringify(secondaryHooks),
