function similarity(a, b) {
  const sa = new Set(String(a || '').split(/\s+/).filter(Boolean));
  const sb = new Set(String(b || '').split(/\s+/).filter(Boolean));
  const inter = [...sa].filter(x => sb.has(x)).length;
  const union = new Set([...sa, ...sb]).size || 1;
  return inter / union;
}

const blockedKeywords = ['??', '??', '??', '??'];

const seenLinks = new Set();
const keptTitles = [];
const out = [];

for (const art of incoming) {
  const title = String(art.source_title || '').trim();
  const link = String(art.source_link || '').trim();

  if (!title || !link) continue;
  if (blockedKeywords.some(k => title.includes(k))) continue;
  if (seenLinks.has(link)) continue;
  if (keptTitles.some(t => similarity(t, title) >= 0.85)) continue;

  seenLinks.add(link);
  keptTitles.push(title);
  out.push({ json: art });
}

return out.slice(0, 12);

return items.map((item, idx) => {
