const images_base64 = imageItems.map((item, i) => {
  const b64 = item.json?.data?.[0]?.b64_json;
  if (!b64) throw new Error(`scene ${i}?? b64_json ??`);
  return b64;
});

if (images_base64.length !== 5) {
  throw new Error(`??? 5? ??, ?? ${images_base64.length}?`);
}

const captions = sceneItems.map(item => item.json.caption || "");
const durations = sceneItems.map(item => item.json.duration || 2);
const scene_json = sceneItems.map(item => item.json);

return [{ json: { images_base64, captions, durations, scene_json } }];

const reelResp = $json || {};

function pickUrl(resp) {
  const direct = [resp.video_url, resp.reel_video_url, resp.url, resp.permanent_url, resp.file_url, resp.output_url];
  for (const d of direct) {
    const v = String(d || '').replace(/\uFEFF/g, '').trim();
    if (v) return v;
  }
  const name = String(resp.fileName || resp.filename || resp.output_file || '').trim();
  if (name) return `https://n8n.mykindredai.com/images/${name}`;
  return '';
}

const reelVideoUrl = pickUrl(reelResp);
const check = reelVideoUrl.toLowerCase();
if (!(check.startsWith('https://') && check.includes('.mp4'))) {
  throw new Error(`Reel generator did not return a valid public HTTPS .mp4 URL: ${JSON.stringify(reelResp).slice(0, 300)}`);
}

const drafts = $items('Parse Draft JSON', 0, 0).map(i => i.json);
return drafts.map(row => {
  const isReel = String(row.content_type || '').toLowerCase() === 'reel';
  return {
    json: {
      ...row,
      video_url: isReel ? reelVideoUrl : String(row.video_url || row.reel_video_url || '')
    }
  };
});

const item = $input.item.json;
const binary = $input.item.binary;
const sourceUrl = String(item.data?.[0]?.url || item.url || '');

return {
  ...item,
  ...(binary ? { binary } : {}),
  cover_url: sourceUrl,
  permanent_url: sourceUrl
};

const header = '[COMPILED CURRENT RULES - ' + '\uBC18\uB4DC\uC2DC \uC6B0\uC120 \uBC18\uC601' + ']';

const rows = items
  .map(i => i.json)
  .filter(r => String(r.rule_text || '').trim())
  .sort((a, b) => Number(a.rule_priority || 999) - Number(b.rule_priority || 999))
  .slice(0, 10);

const current_rules_prompt = rows.length
  ? [header, ...rows.map(r => `- ${String(r.rule_text).trim()}`)].join('\n')
  : header + '\n- No current rules yet. Use strong hook, clear message, and save/share trigger.';

return [{ json: { current_rules_prompt } }];

let rules = '[COMPILED CURRENT RULES - ??? ?? ??]\n- No current rules yet. Use strong hook, clear message, and save/share trigger.';

try {
  const built = $items("Build Current Rules Prompt", 0, 0);
  if (built && built[0] && built[0].json && built[0].json.current_rules_prompt) {
    rules = built[0].json.current_rules_prompt;
  }
} catch (e) {
  // fallback ??
}

return items.map(item => ({
  json: {
    ...item.json,
    current_rules_prompt: rules
  }
}));

const reelSlots = ["07:30", "18:30", "22:20", "07:30"];
function kstNow() {
  const now = new Date();
  const parts = new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Seoul", year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(now);
  const y = parts.find(p => p.type === "year").value;
  const m = parts.find(p => p.type === "month").value;
  const d = parts.find(p => p.type === "day").value;
  return `${y}-${m}-${d}`;
}
function extractFirstUrl(value) {
  if (!value) return "";
  if (Array.isArray(value) && value.length) return String(value[0] || "").trim();
  const text = String(value || "").trim();
  if (!text) return "";
  if (text.startsWith("[")) {
    try {
      const parsed = JSON.parse(text);
      if (Array.isArray(parsed) && parsed.length) return String(parsed[0] || "").trim();
    } catch (e) {}
  }
  return text;
}
function isValidPublicMp4(url) {
  const value = String(url || "").trim();
  if (!value || !/^https:\/\//i.test(value)) return false;
  let parsed;
  try { parsed = new URL(value); } catch (e) { return false; }
  const host = String(parsed.hostname || "").toLowerCase();
  if (!host || host === "example.com" || host.endsWith(".example.com")) return false;
  if (/^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[0-1])\.)/.test(host)) return false;
  return /\.mp4($|\?)/i.test(parsed.pathname + parsed.search);
}
function pickReelVideoUrl(row) {
  const candidates = [
    row.video_url,
    row.reel_video_url,
    row.reel_video,
    row.reel_mp4_url,
    row.public_video_url,
    row.video?.url,
    extractFirstUrl(row.video_urls_json),
    extractFirstUrl(row.video_urls),
  ];
  for (const c of candidates) {
    const v = String(c || "").trim();
    if (v) return v;
  }
  return "";
}
const today = kstNow();
const reels = items.filter(i => String(i.json.content_type || "").toLowerCase() === "reel").sort((a, b) => Number(b.json.score || 0) - Number(a.json.score || 0));
const feeds = items.filter(i => String(i.json.content_type || "").toLowerCase() === "feed").sort((a, b) => Number(b.json.score || 0) - Number(a.json.score || 0));
const normalized = [];

reels.forEach((item, idx) => {
  const row = item.json;
  const slot = reelSlots[idx] || "07:30";
  const subtitles = Array.isArray(row.scene_json) ? row.scene_json.map(s => s.caption).filter(Boolean).join(" | ") : String(row.reel_script || row.body || row.final_title || "");
  const imageUrl = String(row.cover_url || row.image_url || row.photo || extractFirstUrl(row.image_urls_json) || extractFirstUrl(row.image_urls) || "").trim();
  const videoUrl = pickReelVideoUrl(row);
  if (!isValidPublicMp4(videoUrl)) return;

  const required = [row.final_title, row.body, subtitles, row.source_link, row.hashtags, slot, videoUrl];
  if (required.some(v => !String(v || "").trim())) return;

  const contentId = String(row.content_key || row.content_id || "").trim();
  normalized.push({
    json: {
      ...row,
      content_id: contentId,
      platform: "reel",
      title: row.final_title,
      body: row.body,
      subtitles,
      source_url: row.source_link,
      hashtags: row.hashtags,
      image_url: imageUrl || String(row.cover_url || row.image_url || "").trim(),
      video_url: videoUrl,
      time_slot: `${today} ${slot}`,
      status: "draft",
      telegram_message_id: "",
      content_key: contentId
    }
  });
});

feeds.forEach((item) => {
  const row = item.json;
  const subtitles = String(row.body || row.final_title || "");
  const imageUrl = String(row.cover_url || row.image_url || row.photo || extractFirstUrl(row.image_urls_json) || extractFirstUrl(row.image_urls) || row.data?.[0]?.url || "").trim();
  const videoUrl = String(row.video_url || row.reel_video_url || row.cover_url || row.photo || imageUrl || "").trim();
  const required = [row.final_title, row.body, subtitles, row.source_link, row.hashtags, imageUrl, videoUrl];
  if (required.some(v => !String(v || "").trim())) return;
  const contentId = String(row.content_key || row.content_id || "").trim();
  normalized.push({ json: { ...row, content_id: contentId, platform: "feed", title: row.final_title, body: row.body, subtitles, source_url: row.source_link, hashtags: row.hashtags, image_url: imageUrl || String(row.cover_url || row.image_url || "").trim(), video_url: videoUrl, time_slot: `${today} 21:58`, status: "draft", telegram_message_id: "", content_key: contentId } });
});

return normalized;

const store = $getWorkflowStaticData('global');

return items.map((item) => ({
  json: {
    ...item.json,
    sheet_setup_state: store.sheet_setup_done ? 'continue' : 'setup'
  }
}));

const store = $getWorkflowStaticData('global');
const pending = JSON.parse(store.pending_content_items || '[]');
store.sheet_setup_done = true;
delete store.pending_content_items;

